INSERT OR REPLACE INTO topic_abbreviations(abbreviation_id, alias, canonical, notes) VALUES (2, 'AV node', 'atrioventricular node', 'cardiac conduction');
INSERT OR REPLACE INTO topic_abbreviations(abbreviation_id, alias, canonical, notes) VALUES (3, 'RCA', 'right coronary artery', 'coronary circulation');
INSERT OR REPLACE INTO topic_abbreviations(abbreviation_id, alias, canonical, notes) VALUES (4, 'LCA', 'left coronary artery', 'coronary circulation');
INSERT OR REPLACE INTO topic_abbreviations(abbreviation_id, alias, canonical, notes) VALUES (5, 'LAD', 'left anterior descending artery', 'coronary circulation');
